hints.text:
Una biblioteca guarda los libros ordenados por año y quiere saber cuál es el primero publicado en un año dado o después.

function primerLibroDesde(anios, anio) {
  let izq = 0;
  let der = anios.length;
  while (izq < der) {
    const medio = Math.floor((izq + der) / 2);
    if (anios[medio] < anio) {
      izq = medio + 1;
    } else {
      der = medio;
    }
  }
  return izq;
}
